import {FOUNDATION_WAVE_DEFAULTS,restoreFoundationWaves} from './foundation-wave-settings.mjs';
export const VISUAL_DEFAULTS={mode:'spectrum',gain:1,time:40,trail:65,range:96,smoothing:70,peak:60,auto:true,waveformSmoothing:65,...FOUNDATION_WAVE_DEFAULTS};
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
export function restoreVisual(saved){const state={...VISUAL_DEFAULTS};if(!saved||typeof saved!=='object')return state;if(['scope','spectrum','vector'].includes(saved.mode))state.mode=saved.mode;for(const [key,min,max,step]of [['gain',.5,8,.5],['time',10,100,5],['trail',0,100,5],['range',48,120,12],['smoothing',0,95,5],['peak',0,100,5],['waveformSmoothing',0,100,1]])if(Number.isFinite(saved[key]))state[key]=min+Math.round((clamp(saved[key],min,max)-min)/step)*step;if(typeof saved.auto==='boolean')state.auto=saved.auto;Object.assign(state,restoreFoundationWaves(saved));return state;}
export function stereoMetrics(left,right){let ll=0,rr=0,lr=0,peak=0;const n=Math.min(left.length,right.length);for(let i=0;i<n;i++){const l=left[i],r=right[i];ll+=l*l;rr+=r*r;lr+=l*r;peak=Math.max(peak,Math.abs(l),Math.abs(r));}const energy=Math.sqrt(ll*rr);return {peak,rms:n?Math.sqrt((ll+rr)/(2*n)):0,correlation:energy>1e-12?clamp(lr/energy,-1,1):null};}
export function vectorPoint(left,right){return {x:(right-left)/Math.SQRT2,y:(left+right)/Math.SQRT2};}
export function scopeWindow(samples,count){count=clamp(Math.round(count),2,samples.length);const latest=samples.length-count;for(let i=latest;i>Math.max(0,latest-count);i--)if(samples[i-1]<=0&&samples[i]>0)return {start:i,count};return {start:latest,count};}
export function spectrumBands(db,rate,fftSize,count=64){const max=Math.min(20000,rate/2),min=20,bands=new Float32Array(count);for(let i=0;i<count;i++){const low=min*(max/min)**(i/count),high=min*(max/min)**((i+1)/count),a=clamp(Math.floor(low*fftSize/rate),0,db.length-1),b=clamp(Math.ceil(high*fftSize/rate),a+1,db.length);let value=-Infinity;for(let j=a;j<b;j++)value=Math.max(value,db[j]);bands[i]=value;}return bands;}
export function decayPeak(previous,current,dt,persistence){return Math.max(current,previous-dt*(72-persistence*.6));}
// The analysers are a passive branch of the post-volume stereo master. They
// never reconnect, replace, or feed back into the audible destination path.
export function mixSpectrum(left,right,out){for(let i=0;i<out.length;i++)out[i]=10*Math.log10((10**(left[i]/10)+10**(right[i]/10))*.5);return out;}
export function createVisualCapture(context,source){const input=context.createGain(),splitter=context.createChannelSplitter(2),left=context.createAnalyser(),right=context.createAnalyser();for(const node of [left,right]){node.fftSize=8192;node.minDecibels=-120;node.maxDecibels=0;}input.channelCount=2;input.channelCountMode='explicit';input.channelInterpretation='speakers';source.connect(input);input.connect(splitter);splitter.connect(left,0);splitter.connect(right,1);const l=new Float32Array(left.fftSize),r=new Float32Array(right.fftSize),dl=new Float32Array(left.frequencyBinCount),dr=new Float32Array(right.frequencyBinCount),db=new Float32Array(left.frequencyBinCount);db.fill(-Infinity);return {context,left:l,right:r,db,read(smoothing=70,spectrum=true){if(context.state==='closed'){l.fill(0);r.fill(0);db.fill(-Infinity);}else{left.getFloatTimeDomainData(l);right.getFloatTimeDomainData(r);if(spectrum){left.smoothingTimeConstant=right.smoothingTimeConstant=smoothing/100;left.getFloatFrequencyData(dl);right.getFloatFrequencyData(dr);mixSpectrum(dl,dr,db);}}return {left:l,right:r,db,rate:context.sampleRate,fftSize:left.fftSize};},dispose(){for(const node of [input,splitter,left,right])node.disconnect();try{source.disconnect(input);}catch{}}};}
